import { Injectable, computed, inject } from '@angular/core';
import { Claim, Claims, bound } from './claims';
import { People, Person, gradeOn } from './people';
import { Period, Periods } from './periods';
import { Rates, hundredths, money } from './rates';
import { Session } from './session';

/** The statuses claims are counted by, in the order the screen shows them. */
export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'] as const;

// The due figures the screen shows, worked out in one place so the people list, the periods list,
// the summary and the header always agree.
@Injectable({ providedIn: 'root' })
export class Figures {
  private readonly claims = inject(Claims);
  private readonly people = inject(People);
  private readonly periods = inject(Periods);
  private readonly rates = inject(Rates);
  private readonly session = inject(Session);

  /** A person's due-total: the sum of their figures, at most the sheet's cap. Null (n/a) is not capped. */
  dueCents(p: Person): bigint | null {
    const sum = this.sumCents(p);
    const cap = this.capCents();
    return sum !== null && cap !== null && sum > cap ? cap : sum;
  }

  /** How far the sum of a person's figures is above the sheet's cap; 0 when it is not (or is n/a). */
  excessCents(p: Person): bigint {
    const sum = this.sumCents(p);
    const cap = this.capCents();
    return sum !== null && cap !== null && sum > cap ? sum - cap : 0n;
  }

  private capCents(): bigint | null {
    const cap = this.session.cap();
    return cap === null ? null : hundredths(cap);
  }

  /** The sum of the figures of a person's claims that count live (not left out by a hold): a settled claim's frozen due, else the
   *  figure their last statement bound it to, else its live due at the rate in force on its date (a
   *  claim with no figure adds nothing). Null when the grade in force on the sheet's today has no rate
   *  there and no claim has a figure. */
  sumCents(p: Person): bigint | null {
    let sum = 0n;
    let keptFigure = false;
    for (const c of this.claims.live().filter((c) => c.personId === p.id)) {
      if (c.settledDue !== null || (bound(c) && c.statedDue !== null)) keptFigure = true;
      // a claim priced at the grade in force on its date keeps a figure too
      else if (!bound(c) && this.rates.inForce(gradeOn(p.grades, c.date), c.date) !== undefined) keptFigure = true;
      sum += this.figureCents(c, p);
    }
    const today = this.session.today();
    const rated = today ? this.rates.inForce(gradeOn(p.grades, today), today) !== undefined : false;
    return rated || keptFigure ? sum : null;
  }

  /** Everyone's (capped) due-total added up, skipping those whose grade has no rate. */
  readonly dueTotal = computed(() =>
    money(this.people.people().reduce((sum, p) => sum + (this.dueCents(p) ?? 0n), 0n)),
  );

  /** The due of everyone's overdue claims that count, added up. */
  readonly overdueTotal = computed(() =>
    money(this.people.people().reduce((sum, p) => sum + this.overdueCents(p), 0n)),
  );

  /** The number of claims in each status, in the order of STATUSES. */
  readonly statusCounts = computed(() => {
    const claims = this.claims.claims();
    return STATUSES.map((status) => ({ status, count: claims.filter((c) => c.status === status).length }));
  });

  /** A person's claims that count live and are overdue. */
  overdue(p: Person): Claim[] {
    return this.claims.live().filter((c) => c.personId === p.id && this.claims.overdue(c));
  }

  /** The due of a person's overdue claims that count, added up. */
  overdueCents(p: Person): bigint {
    return this.overdue(p).reduce((sum, c) => sum + this.figureCents(c, p), 0n);
  }

  /** A claim's figure: its settled due, else the figure its person's last statement bound it to (not
   *  while PENDING), else its live due at the rate in force on its date, an overdue claim's late charge on top;
   *  nothing when it has no figure. */
  figureCents(c: Claim, p: Person): bigint {
    if (c.settledDue !== null) return hundredths(c.settledDue);
    const f = bound(c)
      ? (c.statedDue === null ? 0n : hundredths(c.statedDue))
      : (this.rates.dueCents(hundredths(c.amount), gradeOn(p.grades, c.date), c.date, this.claims.roundingDate(c)) ?? 0n);
    return f + this.claims.lateCents(c, f);
  }

  /** The grade in force on the sheet's today, the one the list shows. */
  gradeToday(p: Person): string {
    const today = this.session.today();
    return today ? gradeOn(p.grades, today) : p.grade;
  }

  /** Each period's live due-total for each person, in cents, by period id then person id: the figures
   *  of the person's claims that count live whose date falls in it — a settled claim's frozen due, else
   *  as its person's last statement bound it, else its live due, an overdue claim's late charge on top
   *  (a claim with no figure adds nothing). */
  private readonly livePersonPeriodCents = computed(() => {
    const grades = new Map(this.people.people().map((p) => [p.id, p.grades]));
    const sums = new Map<number, Map<number, bigint>>();
    for (const c of this.claims.live()) {
      const period = this.periods.of(c.date);
      if (!period) continue;
      let due: bigint | null;
      if (c.settledDue !== null) due = hundredths(c.settledDue);
      else if (bound(c)) due = c.statedDue === null ? null : hundredths(c.statedDue);
      else {
        const grade = grades.get(c.personId);
        due = grade === undefined ? null : this.rates.dueCents(hundredths(c.amount), gradeOn(grade, c.date), c.date, this.claims.roundingDate(c));
      }
      if (due !== null && c.settledDue === null) due += this.claims.lateCents(c, due);
      const byPerson = sums.get(period.id) ?? new Map<number, bigint>();
      byPerson.set(c.personId, (byPerson.get(c.personId) ?? 0n) + (due ?? 0n));
      sums.set(period.id, byPerson);
    }
    return sums;
  });

  /** A person's due-total for a period: fixed when it was closed (0.00 for a person added since), else
   *  live. */
  personPeriodDue(period: Period, personId: number): string {
    if (period.closed) return period.closedPersonTotals?.[personId] ?? '0.00';
    return money(this.livePersonPeriodCents().get(period.id)?.get(personId) ?? 0n);
  }

  /** Each open period's live due-total, by period id: the sum of the people's live figures for it. */
  readonly periodDueTotals = computed(() => {
    const totals = new Map<number, string>();
    for (const [id, byPerson] of this.livePersonPeriodCents()) {
      totals.set(id, money([...byPerson.values()].reduce((sum, d) => sum + d, 0n)));
    }
    return totals;
  });
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { People, Person, heldOn } from './people';
import { hundredths, rounded } from './rates';
import { Session, daysBetween, isDate } from './session';

export interface Claim {
  id: number;
  personId: number;
  /** Two decimals, as the server stores it. */
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  /** Given when opened: the next on the sheet (1, 2, ...), or while numbering by period the next in its
   *  period (<period name>-1, ...) or in no period (X-1, ...); null while a draft. */
  number: string | null;
  /** The due fixed when it was settled, two decimals; null while its due is live (not settled, or
   *  settled while its grade had no rate). */
  settledDue: string | null;
  /** The user who opened it; null while a draft. That user cannot settle it. */
  openedBy: string | null;
  /** Bound by its person's last statement, which counted it: it shows and totals `statedDue` (not while
   *  PENDING, see `bound`). */
  stated: boolean;
  /** The figure the last statement bound, two decimals; null while unbound, or when that was n/a. */
  statedDue: string | null;
  /** The date it is due by (YYYY-MM-DD): fixed when it was added, its date plus the terms of its person's
   *  grade in force on its date then (the sheet's terms when the grade has none of its own). */
  dueBy: string;
  /** A correction's (a negative amount): the number of the SETTLED claim of the same person it
   *  corrects; null otherwise. */
  corrects: string | null;
  /** Its status log: one line per status it has had, oldest first. */
  statusLog: StatusLine[];
  /** The date it was deferred until (YYYY-MM-DD); null when never deferred. It is deferred only while
   *  OPEN and the sheet's today is before it (see `Claims.deferred`). */
  deferredUntil: string | null;
}

/** A line of a claim's status log: the status it took, who changed it, the sheet's today then
 *  (YYYY-MM-DD), and the due it had then, two decimals (null when n/a). */
export interface StatusLine {
  status: ClaimStatus;
  by: string;
  on: string;
  due: string | null;
}

/** DRAFT when added; DRAFT -> OPEN -> SETTLED, and DRAFT, OPEN or PENDING -> VOID. A clerk settling a
 *  due above the clerk limit makes it PENDING: a steward approves it (SETTLED) or rejects it (OPEN). A
 *  steward can re-settle a SETTLED claim at its figure today. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A status change a claim's buttons ask for. */
export type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject' | 'resettle';

/** Whether a claim in this status counts toward claimed, due-total and every total. */
export function counts(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING' || c.status === 'SETTLED';
}

/** Whether a claim is still open (OPEN or PENDING): it goes overdue, and a hold over its date takes it
 *  out of the live totals unless a statement binds it. */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** Whether a claim is bound by its person's last statement now: a PENDING claim shows and totals its
 *  live figure until rejected back to OPEN. */
export function bound(c: Claim): boolean {
  return c.stated && c.status !== 'PENDING';
}

export interface ClaimFields {
  amount: string;
  /** Blank takes the sheet's today. */
  date: string;
  note: string;
  /** The number of the settled claim a negative amount corrects; blank for any other claim. */
  corrects: string;
}

// The people's claims on the active sheet, newest first, re-read from the server each time the
// sheet is loaded. Sums are kept in whole cents so they add up exactly, and count only OPEN, PENDING
// and SETTLED claims.
@Injectable({ providedIn: 'root' })
export class Claims {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);
  private readonly people = inject(People);

  readonly claims = signal<Claim[]>([]);
  /** The ids of the claims chosen for a bulk action. */
  readonly selected = signal<ReadonlySet<number>>(new Set());
  private loads = 0;

  /** The claims that count in the live totals: those that count, less the OPEN and PENDING claims bound
   *  by no statement and dated within one of their person's holds, and the deferred claims. */
  readonly live = computed(() => {
    const holds = new Map(this.people.people().map((p) => [p.id, p.holds]));
    return this.claims().filter(
      (c) => counts(c) && !(isOpen(c) && !bound(c) && heldOn(holds.get(c.personId) ?? [], c.date)) && !this.deferred(c),
    );
  });

  /** Each person's claimed, in cents, by person id. */
  readonly claimedCents = computed(() => {
    const out = new Map<number, number>();
    for (const c of this.live()) out.set(c.personId, (out.get(c.personId) ?? 0) + cents(c.amount));
    return out;
  });

  /** Everyone's claimed added up, with two decimals. */
  readonly total = computed(() => money(this.live().reduce((sum, c) => sum + cents(c.amount), 0)));

  /** The date a claim is due by: fixed when it was added, from the terms of its person's grade then. */
  dueBy(c: Claim): string {
    return c.dueBy;
  }

  /** Whether a claim is overdue: OPEN or PENDING, not deferred, with its due-by before the sheet's today. */
  overdue(c: Claim): boolean {
    const today = this.session.today();
    return isOpen(c) && !this.deferred(c) && today !== null && this.dueBy(c) < today;
  }

  /** Whether a claim is deferred: OPEN, with a deferred-until date after the sheet's today. Until then it
   *  counts in no total, is not overdue and cannot be settled. */
  deferred(c: Claim): boolean {
    const today = this.session.today();
    return c.status === 'OPEN' && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
  }

  /** The late charge, in cents, on a claim's figure (in cents): while it is overdue, the sheet's late
   *  percent in force on its date of the figure for every full 30 days past its due-by, rounded to cents as its date rounds; none
   *  otherwise, and none on a correction. Never bound by a statement; frozen into the due when settled. */
  lateCents(c: Claim, figureCents: bigint): bigint {
    const today = this.session.today();
    if (!this.overdue(c) || today === null || c.amount.startsWith('-')) return 0n;
    const periods = BigInt(Math.floor(daysBetween(this.dueBy(c), today) / 30));
    return rounded(figureCents * hundredths(this.session.latePctOn(c.date)) * periods, 10000n, this.session.roundsHalfUp(c.date));
  }

  /** The date a claim's figures round by: its own, or for a correction the date of the claim of the same
   *  person it corrects (its own when that is not found). */
  roundingDate(c: Claim): string {
    if (c.corrects === null) return c.date;
    return this.claims().find((o) => o.personId === c.personId && o.number === c.corrects)?.date ?? c.date;
  }

  /** A person's claims, newest first. */
  of(personId: number): Claim[] {
    return this.claims().filter((c) => c.personId === personId);
  }

  /** A person's claimed, with two decimals. */
  claimed(personId: number): string {
    return money(this.claimedCents().get(personId) ?? 0);
  }

  /** Replace a person's claims with these, as the server answered them (newest first). */
  replaceOf(personId: number, theirs: Claim[]): void {
    const byId = new Map(theirs.map((c) => [c.id, c]));
    this.claims.update((cs) => cs.map((c) => (c.personId === personId ? (byId.get(c.id) ?? c) : c)));
  }

  /** Re-read the active sheet's claims from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.claims.set([]);
    this.selected.set(new Set());
    if (!user || !sid) return null;
    try {
      const claims = await firstValueFrom(
        this.http.get<Claim[]>(`${this.url(sid)}/claims`, { headers: { 'X-User': user } }),
      );
      if (load === this.loads) this.claims.set(claims);
      return null;
    } catch (e) {
      return failed('load', e).replace(' claim', ' claims');
    }
  }

  /** Add a claim for a person; an error message when refused. */
  async add(personId: number, f: ClaimFields): Promise<string | null> {
    const refused = this.check(f);
    if (refused) return refused;
    const sid = this.session.sheetId()!;
    try {
      const claim = await firstValueFrom(
        this.http.post<Claim>(`${this.url(sid)}/people/${personId}/claims`, this.body(f), {
          headers: { 'X-User': this.session.user()! },
        }),
      );
      if (this.session.sheetId() === sid) this.claims.update((cs) => [claim, ...cs]);
      return null;
    } catch (e) {
      return failed('add', e);
    }
  }

  /** Quick-add a DRAFT claim dated the sheet's today, with an empty note, for the person with the
   *  name, the server adding them with grade A first when the sheet has no one by it; an error
   *  message when refused. */
  async quickAdd(name: string, amount: string): Promise<string | null> {
    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
    if (!name.trim()) return 'Enter a name.';
    const refused = this.check({ amount, date: '', note: '', corrects: '' });
    if (refused) return refused;
    const sid = this.session.sheetId()!;
    try {
      const added = await firstValueFrom(
        this.http.post<{ person: Person; personAdded: boolean; claim: Claim }>(
          `${this.url(sid)}/quick-claims`,
          { name: name.trim(), amount: amount.trim() },
          { headers: { 'X-User': this.session.user()! } },
        ),
      );
      if (this.session.sheetId() === sid) {
        this.people.people.update((ps) =>
          ps.some((p) => p.id === added.person.id)
            ? ps.map((p) => (p.id === added.person.id ? added.person : p))
            : [...ps, added.person],
        );
        this.claims.update((cs) => [added.claim, ...cs]);
      }
      return null;
    } catch (e) {
      return failed('add', e);
    }
  }

  /** Add a DRAFT claim for each pasted line of name,amount,date,note, in order, for the person on the
   *  sheet with the name; how many were added, or an error message when any line is refused (then the
   *  server adds none). */
  async paste(text: string): Promise<number | string> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    if (!text.trim()) return 'Paste at least one line of name,amount,date,note.';
    try {
      const done = await firstValueFrom(
        this.http.post<{ added: number; claims: Claim[] }>(
          `${this.url(sid)}/claims/paste`,
          { text },
          { headers: { 'X-User': user } },
        ),
      );
      if (this.session.sheetId() === sid) this.claims.update((cs) => [...[...done.claims].reverse(), ...cs]);
      return done.added;
    } catch (e) {
      return failed('add', e).replace(' claim', ' claims');
    }
  }

  /** Change a DRAFT claim's amount, date and note; when refused, the reason and whether it is the
   *  claim itself that refused it (it is no longer a DRAFT) rather than the fields typed. */
  async update(id: number, f: ClaimFields): Promise<{ message: string; onClaim: boolean } | null> {
    const refused = this.check(f);
    if (refused) return { message: refused, onClaim: false };
    const sid = this.session.sheetId()!;
    try {
      const claim = await firstValueFrom(
        this.http.put<Claim>(`${this.url(sid)}/claims/${id}`, this.body(f), {
          headers: { 'X-User': this.session.user()! },
        }),
      );
      if (this.session.sheetId() === sid) this.claims.update((cs) => cs.map((c) => (c.id === id ? claim : c)));
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 409) {
        return { message: message(e) ?? 'Only a DRAFT claim can be edited.', onClaim: true };
      }
      return { message: failed('save', e), onClaim: false };
    }
  }

  /** Open, settle, void, approve, reject or re-settle a claim (a rejection with its reason); an error message
   *  when refused. */
  async act(id: number, action: ClaimAction, reason = ''): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    if (action === 'reject' && !reason.trim()) return 'Give a reason to reject the claim.';
    try {
      const body = action === 'reject' ? { reason: reason.trim() } : null;
      const claim = await firstValueFrom(
        this.http.post<Claim>(`${this.url(sid)}/claims/${id}/${action}`, body, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.claims.update((cs) => cs.map((c) => (c.id === id ? claim : c)));
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 409) return refusal(e, action);
      return failed(action, e);
    }
  }

  /** Defer an OPEN claim to a date after the sheet's today; an error message when refused. */
  async defer(id: number, until: string): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    if (!isDate(until.trim())) return 'Enter the date to defer to as YYYY-MM-DD.';
    try {
      const claim = await firstValueFrom(
        this.http.post<Claim>(`${this.url(sid)}/claims/${id}/defer`, { until: until.trim() }, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.claims.update((cs) => cs.map((c) => (c.id === id ? claim : c)));
      return null;
    } catch (e) {
      return failed('defer', e);
    }
  }

  /** Move a DRAFT, OPEN or PENDING claim to another person (a steward's action): it becomes their newest
   *  claim, unbound from any statement; an error message when refused. */
  async reassign(id: number, personId: number | null): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    if (personId === null) return 'Choose the person to move the claim to.';
    try {
      const claim = await firstValueFrom(
        this.http.post<Claim>(`${this.url(sid)}/claims/${id}/reassign`, { personId }, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.claims.update((cs) => [claim, ...cs.filter((c) => c.id !== id)]);
      return null;
    } catch (e) {
      return failed('reassign', e);
    }
  }

  /** Choose a claim for a bulk action, or leave it out. */
  select(id: number, on: boolean): void {
    this.selected.update((s) => {
      const next = new Set(s);
      if (on) next.add(id);
      else next.delete(id);
      return next;
    });
  }

  /** Open the chosen claims together, the server numbering them in list order and leaving each that
   *  cannot be opened as it is; how many were opened and refused, or an error message. */
  async bulkOpen(): Promise<{ opened: number; refused: number } | string> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    const claimIds = [...this.selected()];
    if (claimIds.length === 0) return 'Select the claims to open.';
    try {
      const done = await firstValueFrom(
        this.http.post<{ opened: number; refused: number; claims: Claim[] }>(
          `${this.url(sid)}/claims/bulk-open`,
          { claimIds },
          { headers: { 'X-User': user } },
        ),
      );
      if (this.session.sheetId() === sid) {
        const byId = new Map(done.claims.map((c) => [c.id, c]));
        this.claims.update((cs) => cs.map((c) => byId.get(c.id) ?? c));
        this.selected.set(new Set());
      }
      return { opened: done.opened, refused: done.refused };
    } catch (e) {
      return failed('open', e).replace(' claim', ' claims');
    }
  }

  /** Settle the chosen claims together, the server settling them in list order as a single settle would
   *  (one a clerk puts PENDING counts as settled) and leaving each that cannot be settled as it is; how
   *  many were settled and refused, or an error message. */
  async bulkSettle(): Promise<{ settled: number; refused: number } | string> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    const claimIds = [...this.selected()];
    if (claimIds.length === 0) return 'Select the claims to settle.';
    try {
      const done = await firstValueFrom(
        this.http.post<{ settled: number; refused: number; claims: Claim[] }>(
          `${this.url(sid)}/claims/bulk-settle`,
          { claimIds },
          { headers: { 'X-User': user } },
        ),
      );
      if (this.session.sheetId() === sid) {
        const byId = new Map(done.claims.map((c) => [c.id, c]));
        this.claims.update((cs) => cs.map((c) => byId.get(c.id) ?? c));
        this.selected.set(new Set());
      }
      return { settled: done.settled, refused: done.refused };
    } catch (e) {
      return failed('settle', e).replace(' claim', ' claims');
    }
  }

  private check(f: ClaimFields): string | null {
    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
    if (!/^-?\d+(\.\d{1,2})?$/.test(f.amount.trim())) return 'Enter an amount with up to two decimals.';
    if (f.date.trim() && !isDate(f.date.trim())) return 'Enter a date as YYYY-MM-DD.';
    const corrects = f.corrects.trim();
    if (corrects.length > 220) return 'Enter the number of the claim it corrects.';
    if (f.amount.trim().startsWith('-') && !corrects) {
      return 'A negative amount is a correction: name the number of the settled claim it corrects.';
    }
    return null;
  }

  private body(f: ClaimFields): { amount: string; date: string | null; note: string; corrects: string | null } {
    const corrects = f.corrects.trim();
    return {
      amount: f.amount.trim(),
      date: f.date.trim() || null,
      note: f.note.trim(),
      corrects: corrects || null,
    };
  }

  private url(sid: string): string {
    return `/api/sheets/${encodeURIComponent(sid)}`;
  }
}

/** An amount written with up to two decimals, perhaps negative, in whole cents. */
function cents(amount: string): number {
  if (amount.startsWith('-')) return -cents(amount.slice(1));
  const [whole, frac = ''] = amount.split('.');
  return Number(whole) * 100 + Number((frac + '00').slice(0, 2));
}

/** Cents as an amount with two decimals. */
function money(cents: number): string {
  if (cents < 0) return `-${money(-cents)}`;
  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
}

function refusal(e: HttpErrorResponse, action: ClaimAction): string {
  return message(e) ?? `This claim's status does not allow it to ${action}.`;
}

/** The reason the server gave for a refusal, when it gave one. */
function message(e: HttpErrorResponse): string | null {
  const err: unknown = e.error;
  if (err && typeof err === 'object' && 'message' in err && typeof err.message === 'string' && err.message) {
    return err.message;
  }
  return null;
}

function failed(what: string, e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 409) return message(e) ?? `Could not ${what} claim (409).`;
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter an amount with up to two decimals.';
  return e instanceof HttpErrorResponse ? `Could not ${what} claim (${e.status}).` : `Could not ${what} claim.`;
}

import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Claim } from './claims';
import { Session } from './session';

export const GRADES = ['A', 'B', 'C'] as const;

/** A grade a person was given, from a date (YYYY-MM-DD); null for the first, from the beginning of time. */
export interface GradeFrom {
  grade: string;
  from: string | null;
}

/** The grade in force on a date (YYYY-MM-DD): the one whose from-date is the latest on or before it. */
export function gradeOn(grades: GradeFrom[], date: string): string {
  let found: string | undefined;
  for (const g of grades) {
    if (found === undefined || g.from === null || g.from <= date) found = g.grade;
  }
  return found ?? '';
}

/** A hold on a person: from a date (null for the beginning of time) to a date (null while it has no
 *  end), both inclusive. */
export interface Hold {
  from: string | null;
  to: string | null;
}

/** Whether one of the holds covers a date (YYYY-MM-DD). */
export function heldOn(holds: Hold[], date: string): boolean {
  return holds.some((h) => (h.from === null || h.from <= date) && (h.to === null || date <= h.to));
}

export interface Person {
  id: number;
  name: string;
  /** The grade in force on the sheet's today when the server answered. */
  grade: string;
  /** Every grade they were given, the first (no from-date) first, then by from-date. */
  grades: GradeFrom[];
  /** Moved on by each save; an edit made from an older version is refused. */
  version: number;
  /** How many statements were taken of them. */
  statementCount: number;
  /** The last statement's due-total, two decimals or n/a; null before their first. */
  statedTotal: string | null;
  /** The sheet's today when the last statement was taken; null before their first. */
  statementDate: string | null;
  /** Whether a retirement date is set: then they count as retired at once, whatever the date. */
  retired: boolean;
  /** The date they are retired from (YYYY-MM-DD); null while not retired. */
  retiredFrom: string | null;
  /** Whether they have any hold at all. */
  held: boolean;
  /** Their holds, by from-date: an OPEN or PENDING claim dated within one, and bound by no statement,
   *  counts in no live total. */
  holds: Hold[];
  /** The ids of the other people on the sheet they have named as their patrons. */
  patronIds: number[];
}

/** A person after a statement, with their claims as it bound them, newest first. */
export interface Statement {
  person: Person;
  claims: Claim[];
}

/** A refused save: why, and the person as stored now when someone else saved them first. */
export interface Refusal {
  error: string;
  current?: Person;
}

export interface PersonFields {
  name: string;
  grade: string;
  /** The date an edit's grade applies from (YYYY-MM-DD); blank takes the sheet's today. */
  gradeFrom?: string;
}

// The people on the active sheet, in the order they were added, re-read from the server each
// time the sheet is loaded.
@Injectable({ providedIn: 'root' })
export class People {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly people = signal<Person[]>([]);
  /** Whether the list shows retired people; belongs to the screen, so loading a sheet leaves it. */
  readonly showRetired = signal(false);
  private loads = 0;

  /** Re-read the active sheet's people from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.people.set([]);
    if (!user || !sid) return null;
    try {
      const people = await firstValueFrom(
        this.http.get<Person[]>(this.url(sid), { headers: { 'X-User': user } }),
      );
      if (load === this.loads) this.people.set(people);
      return null;
    } catch (e) {
      return failed('load', e).replace(' person', ' people');
    }
  }

  /** Add a person; an error message when refused. */
  async add(f: PersonFields): Promise<string | null> {
    const refused = this.check(f);
    if (refused) return refused;
    const sid = this.session.sheetId()!;
    try {
      const person = await firstValueFrom(
        this.http.post<Person>(this.url(sid), this.body(f), { headers: { 'X-User': this.session.user()! } }),
      );
      if (this.session.sheetId() === sid) this.people.update((ps) => [...ps, person]);
      return null;
    } catch (e) {
      return failed('add', e);
    }
  }

  /** Change a person's name and grade, from the version the editor loaded; the refusal when
   *  refused, carrying the person as stored now when someone else saved them in the meantime. */
  async update(id: number, version: number, f: PersonFields): Promise<Refusal | null> {
    const refused = this.check(f);
    if (refused) return { error: refused };
    const sid = this.session.sheetId()!;
    const put = (person: Person) => {
      if (this.session.sheetId() === sid) this.people.update((ps) => ps.map((p) => (p.id === id ? person : p)));
    };
    try {
      put(
        await firstValueFrom(
          this.http.put<Person>(`${this.url(sid)}/${id}`, { ...this.body(f), gradeFrom: f.gradeFrom?.trim() || null, version }, {
            headers: { 'X-User': this.session.user()! },
          }),
        ),
      );
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 412) {
        const current = e.error as Person;
        put(current);
        return { error: 'Someone else has changed this person. Their values are shown; review and save again.', current };
      }
      return { error: failed('save', e) };
    }
  }

  /** Take a person's statement: the person and their claims as it left them, or an error message
   *  when refused. */
  async statement(id: number): Promise<Statement | string> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    try {
      const stated = await firstValueFrom(
        this.http.post<Statement>(`${this.url(sid)}/${id}/statement`, null, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) {
        this.people.update((ps) => ps.map((p) => (p.id === id ? stated.person : p)));
      }
      return stated;
    } catch (e) {
      return failed('take statement of', e);
    }
  }

  /** Retire a person from a date (blank takes the sheet's today); an error message when refused. */
  async retire(id: number, from: string): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    const d = from.trim();
    if (d && !/^\d{4}-\d{2}-\d{2}$/.test(d)) return 'Enter a date as YYYY-MM-DD.';
    try {
      const person = await firstValueFrom(
        this.http.post<Person>(`${this.url(sid)}/${id}/retire`, { from: d || null }, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.people.update((ps) => ps.map((p) => (p.id === id ? person : p)));
      return null;
    } catch (e) {
      return failed('retire', e);
    }
  }

  /** Put a person on hold from a date (blank takes the sheet's today) to a date (blank: no end); an
   *  error message when refused. */
  async hold(id: number, from: string, to: string): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    const f = from.trim();
    const t = to.trim();
    const date = /^\d{4}-\d{2}-\d{2}$/;
    if ((f && !date.test(f)) || (t && !date.test(t))) return 'Enter a date as YYYY-MM-DD.';
    try {
      const person = await firstValueFrom(
        this.http.post<Person>(`${this.url(sid)}/${id}/holds`, { from: f || null, to: t || null }, {
          headers: { 'X-User': user },
        }),
      );
      if (this.session.sheetId() === sid) this.people.update((ps) => ps.map((p) => (p.id === id ? person : p)));
      return null;
    } catch (e) {
      return failed('hold', e);
    }
  }

  /** Name another person on the sheet as a person's patron; an error message when refused. */
  async addPatron(id: number, patronId: number): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    if (patronId === id) return 'A person cannot be their own patron.';
    try {
      const person = await firstValueFrom(
        this.http.post<Person>(`${this.url(sid)}/${id}/patrons`, { patronId }, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.people.update((ps) => ps.map((p) => (p.id === id ? person : p)));
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 409) {
        const err: unknown = e.error;
        if (err && typeof err === 'object' && 'message' in err && typeof err.message === 'string') return err.message;
      }
      return failed('add patron to', e);
    }
  }

  private check(f: PersonFields): string | null {
    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
    if (!f.name.trim()) return 'Enter a name.';
    if (!(GRADES as readonly string[]).includes(f.grade)) return 'Choose a grade.';
    const from = f.gradeFrom?.trim();
    if (from && !/^\d{4}-\d{2}-\d{2}$/.test(from)) return 'Enter the grade\'s from-date as YYYY-MM-DD.';
    return null;
  }

  private body(f: PersonFields): PersonFields {
    return { name: f.name.trim(), grade: f.grade };
  }

  private url(sid: string): string {
    return `/api/sheets/${encodeURIComponent(sid)}/people`;
  }
}

function failed(what: string, e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 409) return 'That name is already in use.';
  return e instanceof HttpErrorResponse ? `Could not ${what} person (${e.status}).` : `Could not ${what} person.`;
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

export interface SheetView {
  id: string;
  today: string;
  /** The largest due a clerk may settle, two decimals; null when there is no limit. */
  clerkLimit: string | null;
  /** The least a claim's live due can be, two decimals. */
  floor: string;
  /** The number of days after a claim's date it is due by. */
  terms: number;
  /** The percent of its figure an overdue claim's due gains for every full 30 days, two decimals. */
  latePct: string;
  /** The policy date (YYYY-MM-DD); null when it is the sheet's today. */
  policyDate: string | null;
  /** The period numbering from-date (YYYY-MM-DD); null when off. */
  periodNumberingFrom: string | null;
  /** The terms of each grade that has its own; a grade without uses the sheet's terms. */
  gradeTerms: Record<string, number>;
  /** The most a person's due-total can be, two decimals; null when there is no cap. */
  cap: string | null;
  /** Every value recorded for a dated setting, by key then from-date. */
  settings: DatedSetting[];
}

/** A value a dated setting (floor, late-pct, terms, terms-<grade>, clerk-limit or cap) takes from a date
 *  on; null for no limit, no cap, or a grade using the sheet's terms. */
export interface DatedSetting {
  key: string;
  from: string;
  value: string | null;
}

/** What the floor, the late percent and the terms are before every from-date. */
const STARTING: Record<string, string> = { floor: '1.00', 'late-pct': '0.00', terms: '14' };

// The signed-in user (a typed name, no password) and the active sheet. Every request to the
// server carries the user's name in the X-User header.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheetId = signal<string | null>(null);
  /** The sheet's today (YYYY-MM-DD): every date decision and default date uses it, never the clock. */
  readonly today = signal<string | null>(null);
  /** Every value recorded for the sheet's dated settings, each from a date. */
  readonly settings = signal<DatedSetting[]>([]);
  /** The sheet's clerk limit (two decimals) in force on its today; null when there is none. */
  readonly clerkLimit = computed(() => this.onToday('clerk-limit'));
  /** The sheet's floor (two decimals) in force on its today: the least a claim's live due can be. */
  readonly floor = computed(() => this.onToday('floor') ?? STARTING['floor']);
  /** The sheet's cap (two decimals) in force on its today: the most a person's due-total can be; null when
   *  there is none. */
  readonly cap = computed(() => this.onToday('cap'));
