content.content:
  /** A person's claims that count live and are overdue. */
  protected overdue(p: Person): Claim[] {
    return this.figures.overdue(p);
  }

  /** The due of a person's overdue claims that count, added up. */
  private overdueCents(p: Person): bigint {
    return this.figures.overdueCents(p);
  }

  protected overdueDue(p: Person): string {
    return money(this.overdueCents(p));
  }

  /** The people a person may choose among as a patron: everyone else on the sheet. */
  protected others(p: Person): Person[] {
    return this.people.people().filter((o) => o.id !== p.id);
  }

  private patronsOf(p: Person): Person[] {
    const ids = new Set(p.patronIds);
    return this.people.people().filter((o) => ids.has(o.id));
  }

  /** A person's patrons' names, sorted, comma and space separated. */
  protected patrons(p: Person): string {
    return this.patronsOf(p).map((o) => o.name).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)).join(', ');
  }

  /** A person's patrons' due-totals added up, skipping those that are n/a; 0.00 with no patrons. */
  protected backing(p: Person): string {
    return money(this.patronsOf(p).reduce((sum, o) => sum + (this.dueCents(o) ?? 0n), 0n));
  }

  protected setPatronChoice(id: number, choice: string): void {
    this.clearActionError(id);
    this.patronChoices.update((cs) => ({ ...cs, [id]: choice }));
  }

  protected async addPatron(p: Person): Promise<void> {
    this.clearActionError(p.id);
    const choice = this.patronChoices()[p.id] ?? '';
    if (!choice) {
      this.patronError.set({ id: p.id, message: 'Choose a patron.' });
      return;
    }
    this.addingPatron.set(p.id);
    try {
      const err = await this.people.addPatron(p.id, Number(choice));
      if (err) this.patronError.set({ id: p.id, message: err });
      else this.patronChoices.update((cs) => ({ ...cs, [p.id]: '' }));
    } finally {
      this.addingPatron.set(null);
    }
  }

  protected due(p: Person): string {
    const d = this.dueCents(p);
    return d === null ? NO_RATE : money(d);
  }

  /** How far the sum of a person's figures is above the sheet's cap; 0.00 when it is not. */
  protected excess(p: Person): string {
    return money(this.figures.excessCents(p));
  }

import { Component, computed, inject } from '@angular/core';
import { Figures } from '../../core/figures';
import { GRADES, People } from '../../core/people';
import { Periods } from '../../core/periods';
import { money } from '../../core/rates';
// The sheet at a glance, from the same figures the lists show: per grade, the people on it today
// (retired people left out) and their due-totals added up (one that is n/a adds nothing); per period,
// its due-total; per status, the claims in it.
@Component({
  selector: 'app-summary',
  template: `
    <section aria-label="Summary" data-testid="summary">
      <h2>Summary</h2>
      <table data-testid="summary-grades">
        <caption>By grade</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">People</th><th scope="col">Due total</th></tr>
        </thead>
        <tbody>
          @for (g of byGrade(); track g.grade) {
            <tr>
              <th scope="row">{{ g.grade }}</th>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-count'">{{ g.count }}</td>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-due-total'">{{ g.dueTotal }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table data-testid="summary-periods">
        <caption>By period</caption>
        <thead>
          <tr><th scope="col">Period</th><th scope="col">Due total</th></tr>
        </thead>
        <tbody>
          @for (p of byPeriod(); track p.name) {
            <tr>
              <th scope="row">{{ p.name }}</th>
              <td [attr.data-testid]="'summary-period-' + p.name + '-due-total'">{{ p.dueTotal }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table data-testid="summary-statuses">
        <caption>By status</caption>
        <thead>
          <tr><th scope="col">Status</th><th scope="col">Claims</th></tr>
        </thead>
        <tbody>
          @for (s of byStatus(); track s.status) {
            <tr>
              <th scope="row">{{ s.status }}</th>
              <td [attr.data-testid]="'summary-status-' + s.status + '-count'">{{ s.count }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class SummaryPanel {
  private readonly people = inject(People);
  private readonly periods = inject(Periods);
  private readonly figures = inject(Figures);
  protected readonly byGrade = computed(() => {
    const current = this.people.people().filter((p) => !p.retired);
    return GRADES.map((grade) => {
      const on = current.filter((p) => this.figures.gradeToday(p) === grade);
      return {
        grade,
        count: on.length,
        dueTotal: money(on.reduce((sum, p) => sum + (this.figures.dueCents(p) ?? 0n), 0n)),
      };
    });
  });
  protected readonly byPeriod = computed(() => {
    const live = this.figures.periodDueTotals();
    return this.periods.periods().map((p) => ({ name: p.name, dueTotal: p.closedTotal ?? live.get(p.id) ?? '0.00' }));
  });
  protected readonly byStatus = this.figures.statusCounts;
}
import { Component, inject } from '@angular/core';
import { Figures } from '../../core/figures';
import { People } from '../../core/people';

// The sheet's counters, always in view: everyone on it (retired people included), the claims in
// each status, and the sheet's due- and overdue-totals — the same figures the summary and the
// people list show.
@Component({
  selector: 'app-header',
  template: `
    <header aria-label="Counters" data-testid="header">
      <dl>
        <div><dt>People</dt><dd data-testid="header-people-count">{{ people.people().length }}</dd></div>
        @for (s of figures.statusCounts(); track s.status) {
          <div><dt>{{ s.status }}</dt><dd [attr.data-testid]="'header-claims-' + s.status + '-count'">{{ s.count }}</dd></div>
        }
        <div><dt>Due total</dt><dd data-testid="header-due-total">{{ figures.dueTotal() }}</dd></div>
        <div><dt>Overdue total</dt><dd data-testid="header-overdue-total">{{ figures.overdueTotal() }}</dd></div>
      </dl>
    </header>
  `,
  styles: `
    header { position: sticky; top: 0; z-index: 1; background: #fff; border-bottom: 1px solid #767676; }
    dl { display: flex; flex-wrap: wrap; gap: 0.25rem 1rem; margin: 0; padding: 0.5rem 0; }
    dt, dd { display: inline; }
    dt::after { content: ': '; }
    dd { margin: 0; font-weight: bold; }
  `,
})
export class HeaderCounters {
  protected readonly people = inject(People);
  protected readonly figures = inject(Figures);
}

